package weeklyassignments;

public class WeeklyAssignment1_EmployeeDetails {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		// TODO Auto-generated method stub
		
					/*Employee Details
				 * Create a Java program to store and print the following employee details:
		Employee ID
		Age
		Salary
		Department Initial
		Whether the employee is permanent
		Use appropriate primitive data types.
		Expected Output:
		Employee ID: 1001
		Age: 28
		Salary: 55000.50
		Department: T
		Permanent: true
				 */
				
				int emp_id=1001;
				System.out.println("Employee ID:"+emp_id);
				
				byte age=28;
				System.out.println("Age:"+age);
				
				float salary=55000.50f;
				System.out.println("Salary:"+salary);
				
				char department_initial='T';
				System.out.println("Department:"+department_initial);
				
				boolean Permanent=true;
				System.out.println("Whether the employee is permanent:"+Permanent);
				

	}

}
